import{_ as n,I as i,c as s,o as h,ah as r,J as t}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"I Ching Coins Method: How the Three-Coin Casting Works","description":"Learn the I Ching coins method: how the three-coin cast works, how lines are formed, and why many readers still use it.","frontmatter":{"title":"I Ching Coins Method: How the Three-Coin Casting Works","description":"Learn the I Ching coins method: how the three-coin cast works, how lines are formed, and why many readers still use it."},"headers":[],"relativePath":"en/articles/i-ching-coins-method/index.md","filePath":"en/articles/i-ching-coins-method/index.md"}'),l={name:"en/articles/i-ching-coins-method/index.md"};function c(d,e,g,m,p,w){const o=i("SeoTopicCluster"),a=i("SeoDownloadPanel");return h(),s("div",null,[e[0]||(e[0]=r('<h1 id="i-ching-coins-method-how-the-three-coin-casting-works" tabindex="-1">I Ching Coins Method: How the Three-Coin Casting Works <a class="header-anchor" href="#i-ching-coins-method-how-the-three-coin-casting-works" aria-label="Permalink to “I Ching Coins Method: How the Three-Coin Casting Works”">​</a></h1><p>The <strong>I Ching coins method</strong> is one of the most common ways to cast a reading today.</p><p>It is popular because it is:</p><ul><li>simple</li><li>fast</li><li>practical</li><li>easy to repeat</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How it works”">​</a></h2><p>In the three-coin method, you cast six times to form six lines from the bottom up.</p><p>Each throw contributes to whether the line becomes:</p><ul><li>yin</li><li>yang</li><li>moving yin</li><li>moving yang</li></ul><p>That means the coins method still preserves line change, which is essential.</p><h2 id="why-people-still-use-it" tabindex="-1">Why people still use it <a class="header-anchor" href="#why-people-still-use-it" aria-label="Permalink to “Why people still use it”">​</a></h2><p>Some readers prefer yarrow stalks, but the coins method remains popular because it is easier to practice regularly.</p><p>For many modern readers, consistency and clarity matter more than ritual complexity.</p><h2 id="what-matters-most" tabindex="-1">What matters most <a class="header-anchor" href="#what-matters-most" aria-label="Permalink to “What matters most”">​</a></h2><p>The key is not just how you cast. The key is whether you can read:</p><ul><li>the original hexagram</li><li>the moving lines</li><li>the changed hexagram</li></ul><p>That is what turns casting into interpretation.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related guides”">​</a></h2><ul><li><a href="./../casting/">Casting Methods</a></li><li><a href="./../moving-lines/">Moving Lines Guide</a></li><li><a href="./../how-to-read-i-ching/">How to Read the I Ching</a></li><li><a href="./../i-ching-for-beginners/">I Ching for Beginners</a></li></ul>',18)),t(o,{title:"Comparisons and Methods Cluster",intro:"These pages focus on casting method, interpretation workflow, and how digital reading tools preserve the structure of the cast.",links:[{text:"Casting Methods",href:"../casting/"},{text:"Moving Lines Guide",href:"../moving-lines/"},{text:"How to Read the I Ching",href:"../how-to-read-i-ching/"},{text:"Online I Ching Reading",href:"../online-i-ching-reading/"},{text:"I Ching AI",href:"../i-ching-ai/"}]}),t(a,{image:"/screenshots/casting-methods.jpg","image-alt":"Three coin casting screenshot",links:[{text:"Casting Methods",href:"../casting/"},{text:"Moving Lines Guide",href:"../moving-lines/"},{text:"How to Read the I Ching",href:"../how-to-read-i-ching/"}]})])}const C=n(l,[["render",c]]);export{f as __pageData,C as default};
